import type { ResourceBundle } from "./types.ts";

export class RcEmitter {
  public static emitTypeScript(bundle: ResourceBundle): string {
    const lines: string[] = [
      "// Generated by win32-svelte Resource Compiler (rc)",
      "// Do not edit manually.",
      "",
    ];

    // 1. Export symbol constants
    lines.push("// Symbol Constants");
    for (const [name, val] of Object.entries(bundle.symbols)) {
      if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)) {
        lines.push(`export const ${name} = ${val};`);
      }
    }
    lines.push("");

    // 2. Export ResourceBundle object
    lines.push("// Resource Bundle");
    lines.push(`export const resources = ${JSON.stringify(bundle, null, 2)};`);
    lines.push("");

    // 3. Named exports for dialog templates
    for (const [key, dlg] of Object.entries(bundle.dialogs)) {
      const exportName = dlg.name && /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(dlg.name)
        ? dlg.name
        : `DIALOG_${key}`;
      // Only export if not already exported as a symbol constant
      if (!bundle.symbols[exportName]) {
        lines.push(`export const ${exportName} = resources.dialogs[${JSON.stringify(key)}];`);
      }
    }

    // 4. Named exports for menus
    for (const [key, menu] of Object.entries(bundle.menus)) {
      const exportName = menu.name && /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(menu.name)
        ? menu.name
        : `MENU_${key}`;
      if (!bundle.symbols[exportName]) {
        lines.push(`export const ${exportName} = resources.menus[${JSON.stringify(key)}];`);
      }
    }

    lines.push("");
    lines.push("export default resources;");
    lines.push("");

    return lines.join("\n");
  }

  public static emitJson(bundle: ResourceBundle, indent = 2): string {
    return JSON.stringify(bundle, null, indent);
  }

  public static emitDts(bundle: ResourceBundle): string {
    const lines: string[] = [
      "import type { ResourceBundle, DialogTemplate, MenuTemplate } from './src/rc/types';",
      "",
    ];

    for (const name of Object.keys(bundle.symbols)) {
      if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)) {
        lines.push(`export const ${name}: number;`);
      }
    }
    lines.push("");
    lines.push("export const resources: ResourceBundle;");
    lines.push("export default resources;");
    lines.push("");

    return lines.join("\n");
  }
}
